import os, requests, json
url=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
s=requests.Session(); s.headers.update({'x-api-key':key})
tool_id='toolshed.g2.bx.psu.edu/repos/devteam/bwa/bwa_mem/0.7.19+galaxy1'
obj=s.get(f'{url}/api/tools/{requests.utils.quote(tool_id, safe=\"\")}', params={'io_details':'true'}).json()
def dump(inp,indent=0):
    pre='  '*indent
    print(pre, 'name=', inp.get('name'), 'type=', inp.get('type'), 'label=', inp.get('label'), 'value=', inp.get('value'), 'optional=', inp.get('optional'))
    if inp.get('type')=='conditional':
        print(pre,' test_param', inp.get('test_param',{}).get('name'), inp.get('test_param',{}).get('value'))
        for c in inp.get('cases',[]):
            print(pre,' case', c.get('value'))
            for ci in c.get('inputs',[]): dump(ci, indent+2)
    if inp.get('type')=='section':
        for ci in inp.get('inputs',[]): dump(ci, indent+1)
for inp in obj['inputs']:
    dump(inp)
